import{z as l,x as i,o as t,c as p,q as B,j as o,D as r,d as E,s as A,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"绩效的持续性","description":"","frontmatter":{"title":"绩效的持续性","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-performance-persistence.md","filePath":"quant/ap-performance-persistence.md","lastUpdated":1791413859000}'),d={name:"quant/ap-performance-persistence.md"};function h(c,a,m,D,u,f){const n=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="绩效的持续性" tabindex="-1">绩效的持续性 <a class="header-anchor" href="#绩效的持续性" aria-label="Permalink to &quot;绩效的持续性&quot;">​</a></h1><div class="epigraph"><p>把赢家与输家按上年排名分组、再看下一年，对角线上的集中度弱得可怜；更要紧的是，测出多少持续性，取决于你怎么构造样本。</p><footer>—— Carhart, On Persistence in Mutual Fund Performance, Journal of Finance, 1997；运气与技能见 Fama and French, Journal of Finance, 2010</footer></div><p><a href="/quant/ap-benchmark-selection">上一课</a>把基准钉成事前契约，横向比较终于可信。缺口是时间维度：<strong>今年的超额会不会重复</strong>。产品层的结论主干<a href="/quant/performance-persistence">业绩持续性</a>已经给出——扣费后持续性大半被动量与费用解释，技能被资金流摊薄；本课不重做那个实证，写<strong>怎么测</strong>：检验的构造选择如何制造或消灭「持续性」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持续性检验是设计敏感的测量：按毛收益还是净 alpha 分组、排序期与持有期各多长、是否控制费用与动量暴露、样本含不含已清盘基金——每一项都改变结论。错法有典型几种：排序期与持有期窗口重叠，相邻观测共享大半数据，t 统计量虚高；只看幸存者，右尾持续性被高估；用同一段公开动量在自变量与因变量两边出现，把市场现象记成经理手艺（Carhart 的教训）；对冲基金样本再叠回填偏差与孵化期筛选——只把孵化成功的记录放进历史，持续性凭空出现。缺口是一套事先声明、经得起样本构建盘问的检验流程。</p><p><span class="marginnote">术语翻译：转移矩阵就像给基金排「座位表」——去年按业绩把全班分成四排，看今年各基金坐到哪一排。若前排的还总在前排，说明座位能延续（有持续性）；若座位每年洗一次牌，排名就只是噪声。</span></p><h3 id="检验的三件套" tabindex="-1">检验的三件套 <a class="header-anchor" href="#检验的三件套" aria-label="Permalink to &quot;检验的三件套&quot;">​</a></h3><p><strong>转移矩阵</strong>：上年分位乘下年分位，看对角线集中度是否超过随机置换。<strong>截面回归</strong>：下期净 alpha 对上期净 alpha 加控制变量（费用、规模、动量暴露），系数是持续性的直接估计。<strong>bootstrap 对照</strong>：Fama–French 的做法——在零技能假设下重抽截面，看观测到的极端业绩能否被运气生成。三件套共同的门槛在样本构建：含清盘、剔除回填、孵化记录全部入史，缺一样结论就漂。</p><p><span class="marginnote">数字实例：12 个月排序、12 个月持有、每月滚动一步，十年数据名义上有约 108 个观测；但相邻两个观测共享 11 个月收益，真正独立的「不重叠块」只有约 10 个。把 108 当独立样本算 t 值，虚高约 \\(\\sqrt{108/10}\\approx 3\\) 倍——显著性大半是重叠送的。</span></p><p><span class="marginnote">用月度滚动数据分组（12 个月排序、往后 12 个月持有、步长 1 个月）会让相邻观测共享 11 个月样本，有效样本量远小于名义观测数；独立化要么拉长步长，要么按重叠块做 bootstrap。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准流程五步：事前声明口径（净、费用、基准、分组规则）；样本处理（含清盘、去回填、孵化全录）；跑三件套并报控制变量；bootstrap 零模型对照；子样本稳健性（发表前后、规模前后、费用档位前后）。最后报告<strong>经济显著性</strong>而不止 t 值：持续性系数折成年化超额是几个基点，扣掉申购费、跟踪成本与容量折价还剩多少。统计上存在、经济上不可投资是常态结果，不是检验失败。</p>',12)),(t(),o(s,null,{default:r(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E4%BA%8B%E5%89%8D%E5%A3%B0%E6%98%8E%3A%20%E5%8F%A3%E5%BE%84%2F%E5%88%86%E7%BB%84%2F%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20SAMPLE%5B%22%E6%A0%B7%E6%9C%AC%3A%20%E5%90%AB%E6%B8%85%E7%9B%98%20%E5%8E%BB%E5%9B%9E%E5%A1%AB%20%E5%AD%B5%E5%8C%96%E5%85%A8%E5%BD%95%22%5D%0A%20%20SAMPLE%20--%3E%20TM%5B%22%E8%BD%AC%E7%A7%BB%E7%9F%A9%E9%98%B5%3A%20%E5%AF%B9%E8%A7%92%E7%BA%BF%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A%20%20SAMPLE%20--%3E%20REG%5B%22%E6%88%AA%E9%9D%A2%E5%9B%9E%E5%BD%92%3A%20%E6%8E%A7%E5%88%B6%E8%B4%B9%E7%94%A8%E4%B8%8E%E5%8A%A8%E9%87%8F%22%5D%0A%20%20SAMPLE%20--%3E%20BOOT%5B%22bootstrap%3A%20%E9%9B%B6%E6%8A%80%E8%83%BD%E5%AF%B9%E7%85%A7%22%5D%0A%20%20TM%20--%3E%20ECON%5B%22%E7%BB%8F%E6%B5%8E%E6%98%BE%E8%91%97%E6%80%A7%3A%20%E6%89%A3%E8%B4%B9%E6%89%A3%E6%88%90%E6%9C%AC%E5%90%8E%E5%89%A9%E4%BD%99%22%5D%0A%20%20REG%20--%3E%20ECON%0A%20%20BOOT%20--%3E%20ECON%0A%20%20ECON%20--%3E%20INV%7B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E5%90%97%3F%22%7D%0A%20%20INV%20--%3E%7C%22%E5%AE%B9%E9%87%8F%E4%B8%8E%E6%88%90%E6%9C%AC%E5%90%83%E5%B0%BD%22%7C%20NO%5B%22%E7%BB%9F%E8%AE%A1%E5%AD%98%E5%9C%A8%20%E7%BB%8F%E6%B5%8E%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20INV%20--%3E%7C%22%E7%BA%A6%E6%9D%9F%E8%A7%92%E8%90%BD%E5%AD%98%E7%95%99%22%7C%20YES%5B%22%E5%B0%8F%E5%AE%B9%E9%87%8F%E6%8C%81%E7%BB%AD%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("持续性弱更多是均衡结果而非测量失败：技能若存在且容量有限，资金追逐把规模推到容量上限，净 alpha 被摊薄到零附近（Berk–Green 的均衡逻辑）；费用差异是确定的、动量是公开的，两者足以填满排序矩阵里的大部分对角线。可投资的持续性只可能残留在容量受约束的角落——小规模、慢信号、封闭结构——而这些地方样本小、噪声大，恰恰是"),e("a",{href:"/quant/multiple-testing-factors"},"多重检验"),E("与"),e("a",{href:"/quant/deflated-sharpe"},"放气夏普"),E("最该盯防的地方：真实的角落持续性，与挖掘出来的假阳性，统计面貌几乎相同。净值曲线课的平滑在这里补一刀：月频平滑让排序更稳，先把波动按自相关还原再测，才不把估值节奏当技能。")],-1)),(t(),o(s,null,{default:r(()=>[A(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SKILL%5B%22%E7%BB%8F%E7%90%86%E5%81%9A%E5%87%BA%E6%AD%A3%E5%87%80%20alpha%22%5D%20--%3E%20FLOW%5B%22%E8%B5%84%E9%87%91%E8%BF%BD%E9%80%90%2C%20%E5%A4%A7%E4%B8%BE%E6%B5%81%E5%85%A5%22%5D%0A%20%20FLOW%20--%3E%20SIZE%5B%22%E8%A7%84%E6%A8%A1%E8%86%A8%E8%83%80%2C%20%E9%80%BC%E8%BF%91%E7%AD%96%E7%95%A5%E5%AE%B9%E9%87%8F%E4%B8%8A%E9%99%90%22%5D%0A%20%20SIZE%20--%3E%20DIL%5B%22%E5%A5%BD%E6%9C%BA%E4%BC%9A%E8%A3%85%E4%B8%8D%E4%B8%8B%E6%96%B0%E9%92%B1%2C%20alpha%20%E8%A2%AB%E6%91%8A%E8%96%84%22%5D%0A%20%20DIL%20--%3E%20ZERO%5B%22%E5%87%80%20alpha%20%E5%9B%9E%E5%88%B0%E9%9B%B6%E9%99%84%E8%BF%91%22%5D%0A%20%20ZERO%20--%3E%7C%22%E5%90%B8%E5%BC%95%E5%8A%9B%E4%B8%8B%E9%99%8D%2C%20%E6%B5%81%E5%85%A5%E6%94%BE%E7%BC%93%22%7C%20FLOW%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">常见误区：初学者容易把「持续性弱」读成「基金经理全是废物」。Berk–Green 的逻辑恰恰相反——技能可能真实存在，只是会被资金流追着摊薄：好业绩引来新钱，新钱挤掉超额。弱的持续性是均衡的产物，不等于技能为零。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>产品层结论以主干课为准，本课不推翻也不重复；检验不外推到「如何选中未来的前十分位」——那是预测问题，样本里没有答案。个人账户里观察到的「持续性」，很大一部分是持有人自身行为的重复，这笔账转给下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续性是设计敏感的测量：分组口径、窗口重叠、样本构建都改写结论。</li><li>三件套：转移矩阵、控制变量后的截面回归、零技能 bootstrap 对照。</li><li>样本三关：含清盘、去回填、孵化全录；缺一关结论就漂。</li><li>报经济显著性：扣费、扣成本、扣容量之后剩下的基点才算数。</li><li>出处：Carhart, <em>Journal of Finance</em>, 1997；Fama and French, <em>Journal of Finance</em>, 2010；Berk and Green, <em>Journal of Political Economy</em>, 2004。</li></ul>',5))])}const _=l(d,[["render",h]]);export{F as __pageData,_ as default};
